mkdir -p /app/submission && cat > /app/submission/main.py <<'PYEOF'
#!/usr/bin/env python3
"""Offline replay auditor for a small SIP identity boundary (Boundary Profile 1).

Reads one JSON envelope from stdin, writes one JSON document to stdout.
Never opens a socket; purely local, deterministic replay of synthetic records.
"""

import hashlib
import json
import re
import sys

MAX_INPUT_BYTES = 33554432
MAX_WIRE_TOTAL = 8388608
MAX_WIRE_CHARS = 131072
MAX_EVENTS = 10000
ANON = "sip:anonymous@anonymous.invalid"


class EnvError(Exception):
    """Invalid envelope: no stdout, exit 2."""


class FieldError(Exception):
    """Section 3 field grammar error (stage 'fields')."""


class SyntaxError_(Exception):
    """Stage 'syntax'."""


# --------------------------------------------------------------------------
# character classes
# --------------------------------------------------------------------------
ASCII_LETTERS = frozenset("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
DIGITS = frozenset("0123456789")
LDH = ASCII_LETTERS | DIGITS | frozenset("-")
USER_CHARS = ASCII_LETTERS | DIGITS | frozenset("-_.!~*'()")
HEXDIG = frozenset("0123456789abcdefABCDEF")
TOKEN_CHARS = ASCII_LETTERS | DIGITS | frozenset("-.!%*_+`'~")
TOKEN_BYTES = frozenset(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
                        b"0123456789-.!%*_+`'~")
WS_BYTES = frozenset(b" \t")

TOKEN_RE = re.compile(r"[A-Za-z0-9\-.!%*_+`'~]+\Z")
CALLID_RE = re.compile(r"[A-Za-z0-9\-_.@]{1,64}\Z")
ID_RE = re.compile(r"[A-Za-z][A-Za-z0-9_\-]{0,31}\Z")
TAGREST_RE = re.compile(
    r"[ \t]*;[ \t]*tag[ \t]*=[ \t]*([A-Za-z0-9\-.!%*_+`'~]{1,32})\Z", re.I)
CSEQ_RE = re.compile(r"([0-9]{1,10})[ \t]+(INVITE|MESSAGE)\Z")
CL_RE = re.compile(r"[0-9]{1,10}\Z")
CL_VALUE_RE = re.compile(r"[0-9]{1,10}\Z")

# header-block bytes: HTAB, CR, LF, SP .. '~'
HEADTBL = bytes(1 if (b == 9 or b == 10 or b == 13 or 32 <= b <= 126) else 0
                for b in range(256))

COMPACT = {"f": "from", "t": "to", "i": "call-id", "l": "content-length"}
REQUIRED = ("from", "to", "call-id", "cseq", "content-length")


# --------------------------------------------------------------------------
# URI language
# --------------------------------------------------------------------------
def parse_host(h):
    if not h or len(h) > 253:
        return None
    labels = h.split(".")
    if len(labels) < 2:
        return None
    last = len(labels) - 1
    for i, lab in enumerate(labels):
        n = len(lab)
        if n < 1 or n > 63:
            return None
        for c in lab:
            if c not in LDH:
                return None
        if lab[0] == "-" or lab[-1] == "-":
            return None
        if i == last and lab[0] not in ASCII_LETTERS:
            return None
    return h.lower()


def parse_port(p):
    n = len(p)
    if n < 1 or n > 5:
        return None
    for c in p:
        if c not in DIGITS:
            return None
    v = int(p)
    if v < 1 or v > 65535:
        return None
    return str(v)


def parse_sip(s):
    """Canonical form of a SIP/SIPS URI, or None."""
    if s[:5].lower() == "sips:":
        sch = "sips"
        rest = s[5:]
    elif s[:4].lower() == "sip:":
        sch = "sip"
        rest = s[4:]
    else:
        return None
    at = rest.find("@")
    if at < 0:
        return None
    user_raw = rest[:at]
    hp = rest[at + 1:]
    if "@" in hp:
        return None
    out = []
    i = 0
    n = len(user_raw)
    while i < n:
        c = user_raw[i]
        if c == "%":
            if i + 2 >= n:
                return None
            a = user_raw[i + 1]
            b = user_raw[i + 2]
            if a not in HEXDIG or b not in HEXDIG:
                return None
            ch = chr(int(user_raw[i + 1:i + 3], 16))
            if ch not in USER_CHARS:
                return None
            out.append(ch)
            i += 3
        elif c in USER_CHARS:
            out.append(c)
            i += 1
        else:
            return None
    if not (1 <= len(out) <= 64):
        return None
    user = "".join(out)
    ci = hp.find(":")
    if ci < 0:
        host_raw, port = hp, ""
    else:
        if hp.find(":", ci + 1) >= 0:
            return None
        host_raw = hp[:ci]
        port = parse_port(hp[ci + 1:])
        if port is None:
            return None
        port = ":" + port
    host = parse_host(host_raw)
    if host is None:
        return None
    return sch + ":" + user + "@" + host + port


def parse_tel(s):
    body = s[4:]
    if not body.startswith("+"):
        return None
    digits = []
    for c in body[1:]:
        if c in DIGITS:
            digits.append(c)
        elif c == "-" or c == "." or c == "(" or c == ")":
            continue
        else:
            return None
    nd = len(digits)
    if nd < 3 or nd > 15:
        return None
    if digits[0] == "0":
        return None
    return "tel:+" + "".join(digits)


def parse_uri(s):
    """Canonical form of a SIP/SIPS/tel URI, or None."""
    if s[:4].lower() == "tel:":
        return parse_tel(s)
    if s[:5].lower() == "sips:" or s[:4].lower() == "sip:":
        return parse_sip(s)
    return None


def uri_kind(canon):
    """'sip' for SIP/SIPS canonical URIs, 'tel' for telephone URIs."""
    if canon[:4] == "tel:":
        return "tel"
    return "sip"


# --------------------------------------------------------------------------
# address (display-name / angle-addr / bare URI) scanning
# --------------------------------------------------------------------------
def scan_quoted(s, i):
    """s[i] == '"'; return index just past the closing quote."""
    n = len(s)
    i += 1
    while True:
        if i >= n:
            raise FieldError("unterminated quoted display name")
        c = s[i]
        if c == "\\":
            if i + 1 < n:
                nxt = s[i + 1]
                if nxt == "\t" or (" " <= nxt <= "~" and nxt != " "):
                    i += 2
                    continue
                if nxt == " ":
                    i += 2
                    continue
            raise FieldError("bad escape in quoted display name")
        if c == '"':
            return i + 1
        if c == "\t" or (" " <= c <= "~"):
            i += 1
            continue
        raise FieldError("bad byte in quoted display name")


def check_unquoted_dn(dn):
    toks = dn.split(" ")
    got = []
    for t in toks:
        if t:
            got.append(t)
    if not got:
        raise FieldError("empty display name")
    for t in got:
        if TOKEN_RE.fullmatch(t) is None:
            raise FieldError("bad unquoted display name token")


def scan_addr(s, terms):
    """Scan one address at the start of ``s``.

    ``terms`` are characters that terminate a bare URI (not consumed).
    Returns ``(uri_text, rest_text)``; raises FieldError on bad syntax.
    """
    n = len(s)
    i = 0
    while i < n and (s[i] == " " or s[i] == "\t"):
        i += 1
    if i >= n:
        raise FieldError("empty address")
    c = s[i]
    if c == '"':
        i = scan_quoted(s, i)
        while i < n and (s[i] == " " or s[i] == "\t"):
            i += 1
        if i >= n or s[i] != "<":
            raise FieldError("junk after quoted display name")
        lt = i
    elif c == "<":
        lt = i
    else:
        limit = n
        for ch in terms:
            p = s.find(ch, i)
            if p >= 0 and p < limit:
                limit = p
        p = s.find("<", i)
        if p >= 0 and p < limit:
            dn = s[i:p].rstrip(" \t")
            if dn:
                check_unquoted_dn(dn)
            lt = p
        else:
            return s[i:limit], s[limit:]
    gt = s.find(">", lt + 1)
    if gt < 0:
        raise FieldError("unmatched angle bracket")
    inner = s[lt + 1:gt]
    if " " in inner or "\t" in inner:
        raise FieldError("whitespace inside angle brackets")
    return inner, s[gt + 1:]


def split_commas(s):
    """Split on commas outside quoted display names and angle brackets."""
    parts = []
    cur = []
    i = 0
    n = len(s)
    in_q = False
    in_b = False
    while i < n:
        c = s[i]
        if in_q:
            if c == "\\":
                cur.append(c)
                i += 1
                if i < n:
                    cur.append(s[i])
                    i += 1
                continue
            if c == '"':
                in_q = False
            cur.append(c)
            i += 1
        elif in_b:
            if c == ">":
                in_b = False
            cur.append(c)
            i += 1
        else:
            if c == '"':
                in_q = True
                cur.append(c)
                i += 1
            elif c == "<":
                in_b = True
                cur.append(c)
                i += 1
            elif c == ",":
                parts.append("".join(cur))
                cur = []
                i += 1
            else:
                cur.append(c)
                i += 1
    parts.append("".join(cur))
    return parts


# --------------------------------------------------------------------------
# request parsing
# --------------------------------------------------------------------------
def parse_request(data):
    """Return a dict of parsed semantics or raise a stage exception.

    Raises SyntaxError_ (stage 'syntax'), _Headers (stage 'headers'),
    _Length (stage 'length') or FieldError (stage 'fields').
    """
    if len(data) > 65536:
        raise SyntaxError_("request too large")
    di = data.find(b"\r\n\r\n")
    if di < 0:
        raise SyntaxError_("missing header/body delimiter")
    head = data[:di]
    body = data[di + 4:]
    if len(head) > 32768:
        raise SyntaxError_("header block too large")
    if b"\x00" in head.translate(HEADTBL):
        raise SyntaxError_("bad header byte")
    if b"\r" in head.replace(b"\r\n", b"") or b"\n" in head.replace(b"\r\n", b""):
        raise SyntaxError_("bare CR or LF in header block")
    lines = head.split(b"\r\n")
    if len(lines) - 1 > 256:
        raise SyntaxError_("too many header lines")
    for ln in lines:
        if len(ln) > 8192:
            raise SyntaxError_("physical line too long")

    sl = lines[0]
    sp = sl.split(b" ")
    if len(sp) != 3:
        raise SyntaxError_("bad start line")
    method_b, target_raw, proto = sp
    if proto != b"SIP/2.0":
        raise SyntaxError_("bad protocol version")
    if method_b != b"INVITE" and method_b != b"MESSAGE":
        raise SyntaxError_("bad method")
    method = method_b.decode("ascii")
    target = parse_sip(target_raw.decode("latin-1"))
    if target is None:
        raise SyntaxError_("bad request URI")

    fields = []
    cur_name = None
    cur_val = None
    for ln in lines[1:]:
        if ln[:1] in (b" ", b"\t"):
            if cur_val is None:
                raise SyntaxError_("continuation without a header")
            cur_val = cur_val.rstrip(b" \t") + b" " + ln.lstrip(b" \t")
        else:
            i = 0
            n = len(ln)
            while i < n and ln[i] in TOKEN_BYTES:
                i += 1
            if i == 0:
                raise SyntaxError_("bad header name")
            j = i
            while j < n and ln[j] in WS_BYTES:
                j += 1
            if j >= n or ln[j] != 0x3A:
                raise SyntaxError_("missing colon in header line")
            if cur_val is not None:
                fields.append((cur_name, cur_val))
            cur_name = ln[:i]
            cur_val = ln[j + 1:]
    if cur_val is not None:
        fields.append((cur_name, cur_val))

    norm = []
    counts = {}
    for nb, vb in fields:
        name = nb.decode("latin-1").lower()
        name = COMPACT.get(name, name)
        norm.append((name, vb.decode("latin-1").strip(" \t")))
        counts[name] = counts.get(name, 0) + 1
    for req in REQUIRED:
        if counts.get(req, 0) != 1:
            raise _Headers("missing or repeated %s" % req)

    values = dict(norm)
    cl = values["content-length"]
    if CL_VALUE_RE.fullmatch(cl) is None:
        raise _Length("malformed Content-Length")
    if int(cl) != len(body):
        raise _Length("Content-Length mismatch")

    # ---- From ----
    try:
        fraw, frest = scan_addr(values["from"], ";")
        m = TAGREST_RE.fullmatch(frest)
        if m is None:
            raise FieldError("bad From tag parameter")
        tag = m.group(1)
        from_canon = parse_uri(fraw)
        if from_canon is None:
            raise FieldError("bad From URI")
    except FieldError:
        raise
    # ---- To ----
    traw, trest = scan_addr(values["to"], "")
    if trest.strip(" \t"):
        raise FieldError("junk after To address")
    to_canon = parse_sip(traw)
    if to_canon is None:
        raise FieldError("To must be a SIP/SIPS URI")
    if to_canon != target:
        raise FieldError("To does not match request URI")
    # ---- Call-ID ----
    call_id = values["call-id"]
    if CALLID_RE.fullmatch(call_id) is None:
        raise FieldError("bad Call-ID")
    # ---- CSeq ----
    m = CSEQ_RE.fullmatch(values["cseq"])
    if m is None or m.group(2) != method:
        raise FieldError("bad CSeq")
    cseq_num = int(m.group(1))
    if cseq_num < 1 or cseq_num > 2147483647:
        raise FieldError("CSeq number out of range")
    # ---- PAI / PPI ----
    pai_rows = []
    ppi_rows = []
    priv_rows = []
    for name, val in norm:
        if name == "p-asserted-identity":
            pai_rows.append(val)
        elif name == "p-preferred-identity":
            ppi_rows.append(val)
        elif name == "privacy":
            priv_rows.append(val)
    pai = parse_id_list(pai_rows) if pai_rows else None
    ppi = parse_id_list(ppi_rows) if ppi_rows else None
    # ---- Privacy ----
    if not priv_rows:
        privacy = "absent"
    else:
        toks = []
        for row in priv_rows:
            for item in row.split(";"):
                it = item.strip(" \t").lower()
                if it != "id" and it != "none":
                    raise FieldError("bad Privacy value")
                toks.append(it)
        if "id" in toks and "none" in toks:
            raise FieldError("mixed Privacy values")
        privacy = "id" if "id" in toks else "none"

    return {
        "method": method,
        "target": target,
        "from": from_canon,
        "tag": tag,
        "call_id": call_id,
        "cseq": cseq_num,
        "pai": pai,
        "ppi": ppi,
        "privacy": privacy,
        "body": body,
    }


class _Headers(Exception):
    pass


class _Length(Exception):
    pass


def parse_id_list(rows):
    items = []
    for row in rows:
        for part in split_commas(row):
            ps = part.strip(" \t")
            if not ps:
                raise FieldError("empty identity list item")
            raw, rest = scan_addr(ps, "")
            if rest.strip(" \t"):
                raise FieldError("junk after identity address")
            canon = parse_uri(raw)
            if canon is None:
                raise FieldError("bad identity URI")
            items.append(canon)
    if len(items) > 2:
        raise FieldError("too many identity addresses")
    if len(items) == 2:
        k0 = uri_kind(items[0])
        k1 = uri_kind(items[1])
        if k0 == k1 or items[0] == items[1]:
            raise FieldError("bad identity pair")
        if k0 == "tel":
            items = [items[1], items[0]]
    return items


# --------------------------------------------------------------------------
# envelope validation
# --------------------------------------------------------------------------
def need_int(v, lo, hi, what):
    if isinstance(v, bool) or not isinstance(v, int):
        raise EnvError("%s must be an integer" % what)
    if v < lo or v > hi:
        raise EnvError("%s out of range" % what)
    return v


def need_keys(obj, keys, what):
    if not isinstance(obj, dict):
        raise EnvError("%s must be an object" % what)
    if len(obj) != len(keys):
        raise EnvError("%s has wrong key set" % what)
    for k in keys:
        if k not in obj:
            raise EnvError("%s missing key %s" % (what, k))
    return obj


def need_str(v, what):
    if not isinstance(v, str):
        raise EnvError("%s must be a string" % what)
    return v


def _pairs_hook(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise ValueError("duplicate object key")
        d[k] = v
    return d


def _bad_constant(name):
    raise ValueError("invalid JSON constant %s" % name)


def parse_envelope(raw):
    if len(raw) > MAX_INPUT_BYTES:
        raise EnvError("input too large")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise EnvError("malformed UTF-8")
    try:
        doc = json.loads(text, object_pairs_hook=_pairs_hook,
                         parse_constant=_bad_constant)
    except ValueError:
        raise EnvError("malformed JSON")
    need_keys(doc, ("version", "config", "events"), "document")
    v = doc["version"]
    if isinstance(v, bool) or not isinstance(v, int) or v != 1:
        raise EnvError("bad version")
    cfg = doc["config"]
    need_keys(cfg, ("accounts", "peers", "ttl_ms", "capacity"), "config")
    ttl = need_int(cfg["ttl_ms"], 1, 1000000, "ttl_ms")
    capacity = need_int(cfg["capacity"], 1, 10000, "capacity")

    accounts = cfg["accounts"]
    if not isinstance(accounts, list) or len(accounts) > 256:
        raise EnvError("bad accounts list")
    alias_owner = {}
    account_aliases = {}
    account_default = {}
    for acc in accounts:
        need_keys(acc, ("id", "default", "aliases"), "account")
        aid = need_str(acc["id"], "account id")
        if ID_RE.fullmatch(aid) is None:
            raise EnvError("bad account id")
        if aid in account_aliases:
            raise EnvError("duplicate account id")
        aliases = acc["aliases"]
        if not isinstance(aliases, list) or not (1 <= len(aliases) <= 8):
            raise EnvError("bad aliases list")
        aset = set()
        for a in aliases:
            if not isinstance(a, str):
                raise EnvError("alias must be a string")
            canon = parse_uri(a)
            if canon is None or canon != a:
                raise EnvError("alias is not canonical")
            if a == ANON:
                raise EnvError("anonymous URI cannot be an alias")
            owner = alias_owner.get(a)
            if owner is not None:
                raise EnvError("alias belongs to two accounts")
            alias_owner[a] = aid
            aset.add(a)
        dflt = acc["default"]
        if not isinstance(dflt, str) or dflt not in aset:
            raise EnvError("default is not an alias")
        account_aliases[aid] = aset
        account_default[aid] = dflt

    peers = cfg["peers"]
    if not isinstance(peers, list) or not (1 <= len(peers) <= 256):
        raise EnvError("bad peers list")
    peer_map = {}
    for p in peers:
        need_keys(p, ("id", "mode", "accounts"), "peer")
        pid = need_str(p["id"], "peer id")
        if ID_RE.fullmatch(pid) is None:
            raise EnvError("bad peer id")
        if pid in peer_map:
            raise EnvError("duplicate peer id")
        mode = need_str(p["mode"], "peer mode")
        if mode != "access" and mode != "relay":
            raise EnvError("bad peer mode")
        plist = p["accounts"]
        if not isinstance(plist, list):
            raise EnvError("bad peer accounts")
        if mode == "access":
            if plist:
                raise EnvError("access peer must have empty accounts")
        else:
            seen = set()
            for a in plist:
                if not isinstance(a, str) or a not in account_aliases:
                    raise EnvError("peer account unknown")
                if a in seen:
                    raise EnvError("peer account repeated")
                seen.add(a)
            plist = seen
        peer_map[pid] = (mode, plist)

    events = doc["events"]
    if not isinstance(events, list) or len(events) > MAX_EVENTS:
        raise EnvError("bad events list")
    total_wire = 0
    prev_t = -1
    for ev in events:
        need_keys(ev, ("t", "peer", "auth", "egress", "wire_hex"), "event")
        t = need_int(ev["t"], 0, 9007199254740991, "event time")
        if t < prev_t:
            raise EnvError("descending event time")
        prev_t = t
        pid = need_str(ev["peer"], "event peer")
        if pid not in peer_map:
            raise EnvError("unknown peer")
        mode = peer_map[pid][0]
        auth = ev["auth"]
        if auth is not None:
            if not isinstance(auth, str):
                raise EnvError("auth must be a string or null")
            if auth not in account_aliases:
                raise EnvError("unknown auth account")
            if mode == "relay":
                raise EnvError("relay event must have null auth")
        eg = need_str(ev["egress"], "egress")
        if eg != "internal" and eg != "external":
            raise EnvError("bad egress")
        wh = need_str(ev["wire_hex"], "wire_hex")
        if len(wh) > MAX_WIRE_CHARS:
            raise EnvError("wire_hex too long")
        total_wire += len(wh) // 2
        if total_wire > MAX_WIRE_TOTAL:
            raise EnvError("total wire too large")

    return {
        "ttl": ttl,
        "capacity": capacity,
        "alias_owner": alias_owner,
        "account_aliases": account_aliases,
        "account_default": account_default,
        "peers": peer_map,
        "events": events,
    }


# --------------------------------------------------------------------------
# event processing
# --------------------------------------------------------------------------
def run(cfg):
    ttl = cfg["ttl"]
    capacity = cfg["capacity"]
    alias_owner = cfg["alias_owner"]
    account_aliases = cfg["account_aliases"]
    account_default = cfg["account_default"]
    peers = cfg["peers"]

    ledger = {}
    order = []
    results = []
    accepted = 0
    replayed = 0
    rejected = 0

    for idx, ev in enumerate(cfg["events"]):
        t = ev["t"]
        while order and order[0][0] + ttl <= t:
            old = order.pop(0)[1]
            ledger.pop(old, None)

        peer_id = ev["peer"]
        mode, allowed = peers[peer_id]
        auth = ev["auth"]
        egress = ev["egress"]
        wh = ev["wire_hex"]

        res = None
        req = None
        reason = None
        if len(wh) & 1 or not HEXDIG.issuperset(wh):
            reason = "hex"
        else:
            try:
                req = parse_request(bytes.fromhex(wh))
            except SyntaxError_:
                reason = "syntax"
            except _Headers:
                reason = "headers"
            except _Length:
                reason = "length"
            except FieldError:
                reason = "fields"

        if reason is None:
            privacy = req["privacy"]
            ppi = req["ppi"]
            pai = req["pai"]
            from_canon = req["from"]
            if mode == "access":
                if auth is None:
                    reason = "auth"
                else:
                    acc = auth
                    aset = account_aliases[acc]
                    if ppi is not None:
                        ok = True
                        for u in ppi:
                            if u not in aset:
                                ok = False
                                break
                        if not ok:
                            reason = "identity"
                        else:
                            asserted = ppi
                    else:
                        asserted = [account_default[acc]]
            else:
                if ppi is not None or pai is None:
                    reason = "identity"
                else:
                    owner = None
                    ok = True
                    for u in pai:
                        o = alias_owner.get(u)
                        if o is None:
                            ok = False
                            break
                        if owner is None:
                            owner = o
                        elif owner != o:
                            ok = False
                            break
                    if not ok:
                        reason = "identity"
                    elif owner not in allowed:
                        reason = "identity"
                    else:
                        acc = owner
                        asserted = pai
            if reason is None:
                if from_canon in account_aliases[acc]:
                    pass
                elif from_canon == ANON and privacy == "id":
                    pass
                else:
                    reason = "identity"

        if reason is not None:
            rejected += 1
            results.append({"index": idx, "decision": "reject",
                            "reason": reason})
            continue

        selected = asserted[0]
        privacy = req["privacy"]
        if req["privacy"] == "id":
            from_out = ANON
        else:
            from_out = selected
        if egress == "external" and privacy != "none":
            pai_out = []
        else:
            pai_out = asserted

        key = (peer_id, req["call_id"], req["cseq"], req["method"])
        commit = (acc, selected, tuple(asserted), from_canon, req["tag"],
                  req["target"], privacy, egress, req["body"])
        ent = ledger.get(key)
        if ent is not None:
            if ent[0] == commit:
                replayed += 1
                first = ent[1]
                decision = "replay"
            else:
                rejected += 1
                results.append({"index": idx, "decision": "reject",
                                "reason": "conflict"})
                continue
        else:
            if len(ledger) >= capacity:
                old = order.pop(0)[1]
                ledger.pop(old, None)
            ledger[key] = (commit, idx, t)
            order.append((t, key))
            accepted += 1
            first = idx
            decision = "accept"

        results.append({
            "index": idx,
            "decision": decision,
            "first": first,
            "account": acc,
            "identity": selected,
            "from": from_out,
            "pai": list(pai_out),
            "method": req["method"],
            "target": req["target"],
            "call_id": req["call_id"],
            "cseq": req["cseq"],
            "tag": req["tag"],
            "privacy": privacy,
            "body_sha256": hashlib.sha256(req["body"]).hexdigest(),
        })

    return {
        "results": results,
        "accepted": accepted,
        "replayed": replayed,
        "rejected": rejected,
        "live": len(ledger),
    }


def main():
    raw = sys.stdin.buffer.read()
    try:
        cfg = parse_envelope(raw)
    except EnvError as exc:
        sys.stderr.write("invalid envelope: %s\n" % exc)
        return 2
    out = run(cfg)
    sys.stdout.write(json.dumps(out, separators=(",", ":")))
    sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
